import json
import itertools

def solve():
    houses = [1, 2, 3]

    # Attributes as per puzzle
    Names = ["Peter", "Arnold", "Eric"]
    BookGenres = ["science fiction", "mystery", "romance"]
    Smoothies = ["watermelon", "desert", "cherry"]
    Months = ["april", "jan", "sept"]
    Heights = ["average", "very short", "short"]

    solutions = []

    # Helper: find index of a value in a permutation list
    def idx_of(perm, value):
        return perm.index(value)

    for names_perm in itertools.permutations(Names):
        # 7. Eric is in the first house.
        if names_perm[0] != "Eric":
            continue

        for genres_perm in itertools.permutations(BookGenres):
            # 2. Arnold is the person who loves mystery books.
            if genres_perm[idx_of(names_perm, "Arnold")] != "mystery":
                continue

            for months_perm in itertools.permutations(Months):
                # 3. The person whose birthday is in January is not in the first house.
                if months_perm[0] == "jan":
                    continue
                # 5. The person who loves mystery books is the person whose birthday is in September.
                if months_perm[idx_of(genres_perm, "mystery")] != "sept":
                    continue

                for smoothies_perm in itertools.permutations(Smoothies):
                    # 1. The person who likes Cherry smoothies is not in the second house.
                    if smoothies_perm[1] == "cherry":
                        continue
                    # 9. The Watermelon smoothie lover is Eric.
                    if smoothies_perm[idx_of(names_perm, "Eric")] != "watermelon":
                        continue

                    for heights_perm in itertools.permutations(Heights):
                        # 4. The person who is very short is the person who loves romance books.
                        if heights_perm[idx_of(genres_perm, "romance")] != "very short":
                            continue
                        # 6. The person who has an average height is the Desert smoothie lover.
                        if heights_perm[idx_of(smoothies_perm, "desert")] != "average":
                            continue
                        # 8. The Watermelon smoothie lover is the person who is short.
                        if heights_perm[idx_of(smoothies_perm, "watermelon")] != "short":
                            continue

                        # If we reach here, all constraints are satisfied
                        solution_rows = []
                        for h in range(3):
                            solution_rows.append([
                                str(houses[h]),
                                names_perm[h],
                                genres_perm[h],
                                smoothies_perm[h],
                                months_perm[h],
                                heights_perm[h],
                            ])
                        solutions.append(solution_rows)

    if not solutions:
        raise ValueError("No solution found.")
    if len(solutions) > 1:
        # If multiple solutions, pick the first but it's expected to be unique.
        pass

    header = ["House", "Name", "favorite book genres", "favorite smoothie", "birthday month", "heights"]
    output = {
        "solution": {
            "header": header,
            "rows": solutions[0]
        }
    }
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    solve()
